"""Team workspace UI. All decisions are made by the authenticated API."""

TEAM_CSS = r"""
.team-page{max-width:1440px;margin:auto}.team-head{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:24px}.team-head h1{font-size:28px;letter-spacing:-.035em;margin:0 0 8px}.team-muted{color:var(--sub,#697386);font-size:13px;line-height:1.6}.team-tabs{display:flex;gap:6px;flex-wrap:wrap;border-bottom:1px solid var(--line,#e3e7ef);padding-bottom:14px;margin-bottom:18px}.team-tab{border:0;background:transparent;padding:9px 14px;border-radius:8px;color:var(--sub,#697386);font:inherit;cursor:pointer}.team-tab[aria-selected=true]{background:var(--fg,#17212f);color:var(--bg,#fff)}.team-tab span{margin-left:9px;opacity:.7;font-variant-numeric:tabular-nums}.team-list{border:1px solid var(--line,#e3e7ef);border-radius:12px;overflow:hidden;background:var(--card,#fff)}.team-row{display:grid;grid-template-columns:minmax(220px,2.4fr) minmax(100px,1fr) minmax(110px,1fr) minmax(170px,1.4fr) 90px;gap:20px;padding:18px 20px;align-items:center;border-bottom:1px solid var(--line,#e3e7ef)}.team-row:last-child{border:0}.team-row-head{background:var(--bg,#f7f8fa);font-size:12px;color:var(--sub,#697386);padding-top:11px;padding-bottom:11px}.team-title{font-weight:600;font-size:14px;line-height:1.6;overflow-wrap:anywhere}.team-key{color:var(--sub,#697386);font:11px ui-monospace,monospace;letter-spacing:.04em;margin-bottom:5px}.team-tag{display:inline-flex;align-items:center;border:1px solid var(--line,#e3e7ef);border-radius:6px;padding:3px 7px;font-size:11px;line-height:1.4;white-space:normal}.team-tag[data-tone=good]{color:var(--ok,#18794e);background:#effaf3;border-color:#c7e9d3}.team-tag[data-tone=warn]{color:#966324;background:#fff8eb;border-color:#eddbb7}.team-tag[data-tone=bad]{color:var(--bad,#b63131);background:#fff2f2;border-color:#efcccc}.team-btn{font:inherit;cursor:pointer;border:1px solid var(--line,#dce1e9);border-radius:7px;background:var(--card,#fff);color:var(--fg,#17212f);padding:9px 12px;line-height:1.2}.team-btn:hover{border-color:var(--acc,#3662d8)}.team-btn:disabled{opacity:.45;cursor:not-allowed}.team-btn-primary{background:var(--fg,#17212f);border-color:var(--fg,#17212f);color:var(--bg,#fff)}.team-actions{display:flex;flex-wrap:wrap;align-items:center;gap:9px}.team-empty{padding:64px 24px;text-align:center}.team-empty b{display:block;font-size:17px;margin-bottom:10px}.team-note{border-left:3px solid var(--acc,#3662d8);padding:10px 14px;background:var(--bg,#f7f8fa);line-height:1.6;font-size:13px;margin:16px 0}.team-dialog{width:min(940px,calc(100vw - 40px));max-height:90vh;border:1px solid var(--line,#e3e7ef);border-radius:14px;padding:0;color:var(--fg,#17212f);background:var(--card,#fff);box-shadow:0 28px 90px #15243433}.team-dialog::backdrop{background:#10203460;backdrop-filter:blur(3px)}.team-dialog-head{position:sticky;top:0;background:var(--card,#fff);padding:22px 26px;border-bottom:1px solid var(--line,#e3e7ef);display:flex;gap:18px;align-items:flex-start;z-index:1}.team-dialog-head h2{font-size:21px;line-height:1.5;margin:0}.team-dialog-body{padding:22px 26px}.team-section{border-top:1px solid var(--line,#e3e7ef);padding-top:20px;margin-top:22px}.team-section h3{font-size:15px;margin:0 0 14px}.team-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.team-field{display:flex;flex-direction:column;gap:7px;font-size:12px;color:var(--sub,#697386)}.team-field input,.team-field select,.team-field textarea,.team-select{box-sizing:border-box;width:100%;background:var(--card,#fff);color:var(--fg,#17212f);font:14px inherit;border:1px solid var(--line,#dce1e9);border-radius:7px;padding:10px;line-height:1.5}.team-field textarea{resize:vertical;min-height:90px}.team-criteria{display:flex;flex-direction:column;gap:14px}.team-criterion{border:1px solid var(--line,#e3e7ef);border-radius:8px;padding:14px}.team-error{color:var(--bad,#b63131);font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere;padding:10px 0}.team-feedback{color:var(--ok,#18794e);font-size:13px;padding:10px 0}.team-flow{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:16px 0}.team-flow>div{padding:12px;border:1px solid var(--line,#e3e7ef);border-radius:8px;font-size:12px}.team-flow b{display:block;margin-bottom:5px;font-size:13px}.team-code{font-family:ui-monospace,monospace;font-size:12px;overflow-wrap:anywhere}.team-history{font-size:13px;border-bottom:1px solid var(--line,#e3e7ef);padding:12px 0;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}.team-more{margin:18px auto;display:block}.team-statusline{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}.team-description{line-height:1.8;font-size:14px;overflow-wrap:anywhere}.team-dialog details>summary{cursor:pointer;font-weight:600;font-size:14px;padding:8px 0}.team-sr{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:850px){.team-row{grid-template-columns:minmax(180px,2fr) 1fr 100px;gap:12px}.team-row>div:nth-child(2),.team-row>div:nth-child(3){display:none}.team-flow{grid-template-columns:1fr 1fr}.team-head{flex-direction:column}.team-dialog{width:calc(100vw - 20px)}.team-dialog-head,.team-dialog-body{padding:18px}.team-grid{grid-template-columns:1fr}}@media(max-width:520px){.team-row{grid-template-columns:1fr 80px}.team-row>div:nth-child(4){grid-column:1}.team-row>div:last-child{grid-column:2;grid-row:1 / span 2}.team-row-head{display:none}.team-tabs{gap:2px}.team-tab{padding:9px}.team-head h1{font-size:25px}}
"""

TEAM_JS = r"""
const teamState={view:'mine',project:'*',data:null,offset:0,dialog:null,busy:false,generation:0,listRead:0,requests:new Map()};
const teamNames={mine:'我的工作',team:'团队任务',review:'待我复核',unassigned:'待分配'};
function teamBadge(item){const good=['approved','merged','closed'].includes(item.state),bad=['blocked','changes_requested','stale'].includes(item.state);return `<span class="team-tag" data-tone="${good?'good':bad?'bad':'warn'}">${h(item.label)}</span>`}
function teamRequest(){return 'team-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2))}
function teamRow(x){const t=x.ticket,a=x.assignment;return `<div class="team-row"><div><div class="team-key">${h(t.key)} · ${h(t.type)}</div><div class="team-title">${h(t.title)}</div></div><div><div>${h(a.assignee_active?a.assignee:'待分配')}</div>${a.assignee&&!a.assignee_active?`<div class="team-muted">原署名 ${h(a.assignee)}</div>`:''}</div><div>${h(a.reviewer||'待指定')}${a.reviewer&&!a.reviewer_active?'<div class="team-muted">账号已不可用</div>':''}</div><div>${teamBadge(x)}${x.candidate?`<div class="team-muted team-code" style="margin-top:5px">${h(x.candidate.commit.slice(0,10))}</div>`:''}</div><div><button class="team-btn" data-team-open="${h(t.key)}">查看任务</button></div></div>`}
async function vTeam(view='mine',ticketKey=''){
 teamState.view=teamNames[view]?view:'mine';teamState.project=scopeQ();teamState.offset=0;const generation=++teamState.generation,route=location.hash,scope=teamState.project;const main=document.querySelector('#main');
 if(teamState.dialog)teamState.dialog.close();
 main.innerHTML='<div class="team-page"><div class="team-empty" role="status">正在读取团队任务…</div></div>';
 try{const [data,projects]=await Promise.all([get('/api/team?view='+teamState.view+'&project='+encodeURIComponent(teamState.project)),get('/api/projects')]);if(generation!==teamState.generation||route!==location.hash||scope!==scopeQ())return;teamState.data=data;
 main.innerHTML=`<div class="team-page"><div class="team-head"><div><div class="team-key">TEAM WORKSPACE</div><h1>${h(teamNames[teamState.view])}</h1><div class="team-muted">${data.viewer?h(data.viewer)+'，从当前需要你推进的工作开始。':'登录个人账号后，查看分配给你的工作与复核。'}</div></div><label class="team-field">项目<select class="team-select" id="team-project"><option value="*">所有项目</option>${projects.map(p=>`<option value="${h(p.key)}" ${p.key===teamState.project?'selected':''}>${h(p.name)}</option>`).join('')}</select></label></div><div class="team-tabs" role="tablist" aria-label="团队工作视图">${Object.entries(teamNames).map(([key,name])=>`<button class="team-tab" role="tab" aria-selected="${teamState.view===key}" data-team-view="${key}">${name}<span>${data.counts[key]}</span></button>`).join('')}</div>${!data.viewer?'<div class="team-note">当前没有可核对的个人身份。使用自己的账号登录后，才能分配、提交或复核。</div>':''}<div id="team-list" class="team-list"><div class="team-row team-row-head"><div>任务</div><div>负责人</div><div>复核人</div><div>当前进度</div><div>操作</div></div>${data.items.map(teamRow).join('')||`<div class="team-empty"><b>${teamState.view==='review'?'目前没有交给你的复核':'这里还没有任务'}</b><span class="team-muted">${teamState.view==='mine'?'可以到团队任务中查看现有工作，并明确负责人。':'任务的真实进展会显示在这里。'}</span></div>`}</div><button id="team-more" class="team-btn team-more" ${data.has_more?'':'hidden'}>加载更多任务</button><div class="team-muted" style="margin-top:18px">${h(data.boundary)}</div></div>`;
 if(ticketKey){const selected=data.items.find(x=>x.ticket.key===ticketKey)||((await get('/api/team?view=team&ticket='+encodeURIComponent(ticketKey))).items||[])[0];if(selected&&generation===teamState.generation&&route===location.hash&&scope===scopeQ())teamOpen(ticketKey,selected)}
 main.querySelectorAll('[data-team-view]').forEach(b=>b.onclick=()=>{const next='#/team/'+b.dataset.teamView;if(location.hash===next)vTeam(b.dataset.teamView);else location.hash=next});
 document.querySelector('#team-project').onchange=e=>{teamState.project=e.target.value;S.scope=teamState.project;ls.set('tmh.scope',S.scope);if(S.scope!=='*')setProj(S.scope);paintSel();vTeam(teamState.view)};teamWireRows(main);
 document.querySelector('#team-more').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{const more=await get('/api/team?view='+teamState.view+'&project='+encodeURIComponent(teamState.project)+'&offset='+teamState.data.next_offset);if(generation!==teamState.generation||route!==location.hash||scope!==scopeQ())return;teamState.data.items.push(...more.items);teamState.data.next_offset=more.next_offset;teamState.data.has_more=more.has_more;document.querySelector('#team-list').insertAdjacentHTML('beforeend',more.items.map(teamRow).join(''));teamWireRows(main);b.hidden=!more.has_more}catch(error){b.textContent=error.message}finally{b.disabled=false}};
 }catch(error){if(generation===teamState.generation&&route===location.hash&&scope===scopeQ())main.innerHTML=`<div class="team-page"><div class="team-error" role="alert">${h(error.message)}</div><button class="team-btn" id="team-retry">重新读取</button></div>`;document.querySelector('#team-retry')?.addEventListener('click',()=>vTeam(teamState.view))}
}
async function teamRefreshList(){
 const generation=teamState.generation,read=++teamState.listRead,route=location.hash,project=teamState.project,view=teamState.view,wanted=Math.max(50,teamState.data?.items.length||0);let all=[],data;
 do{data=await get('/api/team?view='+view+'&project='+encodeURIComponent(project)+'&offset='+all.length+'&limit='+Math.min(100,wanted-all.length));if(generation!==teamState.generation||read!==teamState.listRead||route!==location.hash||project!==scopeQ())return;all.push(...data.items)}while(data.has_more&&all.length<wanted);
 teamState.data={...data,items:all,next_offset:all.length};const list=document.querySelector('#team-list');if(!list)return;
 list.innerHTML='<div class="team-row team-row-head"><div>任务</div><div>负责人</div><div>复核人</div><div>当前进度</div><div>操作</div></div>'+all.map(teamRow).join('')+(all.length?'':'<div class="team-empty"><b>当前视图已处理完</b><span class="team-muted">可以切换到团队任务继续查看。</span></div>');teamWireRows(list);
 document.querySelectorAll('[data-team-view]').forEach(b=>{const count=b.querySelector('span');if(count)count.textContent=data.counts[b.dataset.teamView]});const more=document.querySelector('#team-more');if(more)more.hidden=!data.has_more;
}
function teamWireRows(root){root.querySelectorAll('[data-team-open]').forEach(b=>b.onclick=()=>teamOpen(b.dataset.teamOpen))}
function teamOptions(selected){return '<option value="">未分配</option>'+teamState.data.members.map(m=>`<option value="${h(m.id)}" ${m.id===selected?'selected':''}>${h(m.name)}</option>`).join('')}
function teamMemoryPanel(m){return `<section class="team-section"><h3>本次验收留下的记忆</h3><p class="team-muted">${h(m.by)} 的${m.result==='pass'?'通过':'退回'}记录${m.pending?'已经保存，记忆沉淀尚未完成。':'已关联记忆 '+h(m.lesson_id)+'；在知识与记忆中查看来源和确认状态。'}</p><div class="team-actions">${m.pending?`<button class="team-btn" id="team-memory-retry" ${m.can_retry?'':'disabled'}>补写本次验收记忆</button>`:''}<button class="team-btn" id="team-memory-open">查看项目记忆</button></div>${m.pending?'<p class="team-muted">补写保留原始验收，不重新验收或发布代码。由原验收人作为当前复核人操作。</p>':''}</section>`}
function teamMemoryFeedback(result){const m=result?.result?.memory;return !m?'':m.pending?'；'+(m.message||'验收已保存，记忆待补写'):'；已关联记忆 '+m.lesson_id+'，请到知识与记忆查看与确认'}
function teamAccessReason(x,action){
 const project=x.ticket.pkey||x.ticket.key.slice(0,x.ticket.key.lastIndexOf('-'));if(typeof accessCanWrite==='function'&&!accessCanWrite(project))return '当前账号对本项目只有查看权限，不能调整分配、提交材料或代替他人确认。';
 if(action==='assign'&&S.meta?.access&&typeof accessProjectRole==='function'&&accessProjectRole(project)!=='manager')return '只有本项目管理员可以调整负责人和独立复核人。';
 if(action==='candidate_preview'&&S.meta?.access)return '租户隔离环境尚不支持固定版本预览。';
 if(['claim','candidate_submit','candidate_verify','candidate_assess','review','candidate_merge','business_accept','run_recheck','candidate_cancel'].includes(action)&&typeof accessCanExecute==='function'&&!accessCanExecute(project))return '当前身份或租户没有 Git 证据核对与执行权限，候选登记、技术检查、人工复核和合并暂不可用。可继续记录任务与交接材料。';return '';
}
function teamAccessGuard(dialog,x){const controls={'team-assign':'assign','team-claim':'claim','team-comment-send':'comment','team-submit':'candidate_submit','team-run-recheck':'run_recheck','team-verify':'candidate_verify','team-preview':'candidate_preview','team-cancel':'candidate_cancel','team-assess':'candidate_assess','team-accept':'review','team-reject':'review','team-merge':'candidate_merge','team-business-pass':'business_accept','team-business-fail':'business_accept','team-memory-retry':'business_accept'};let message='';for(const [id,action]of Object.entries(controls)){const node=dialog.querySelector('#'+id),reason=teamAccessReason(x,action);if(node&&reason){node.disabled=true;node.title=reason;node.setAttribute('aria-description',reason);message=reason}}const note=dialog.querySelector('#team-access-note');if(note){note.textContent=message;note.hidden=!message}}
async function teamOpen(key,item){
 if(teamState.busy)return;const x=item||teamState.data.items.find(i=>i.ticket.key===key);if(!x)return;
 if(teamState.dialog){teamState.dialog.close();teamState.dialog.remove()}
 const dialog=document.createElement('dialog');dialog.className='team-dialog';dialog.setAttribute('aria-labelledby','team-detail-title');teamState.dialog=dialog;
 const t=x.ticket,a=x.assignment,c=x.candidate,active=!!teamState.data.viewer,technical={not_started:'尚未开始',pending:'尚未通过',running:'检查中',tests_passed:'构建测试通过',passed:'当前技术证据通过'},human={not_requested:'尚未提交复核',pending:'等待复核',accepted:'当前复核通过',rejected:'已退回'};
 dialog.innerHTML=`<div class="team-dialog-head"><div style="flex:1"><div class="team-key">${h(t.key)}</div><h2 id="team-detail-title">${h(t.title)}</h2><div class="team-statusline">${teamBadge(x)}<a href="#/t/${h(t.key)}" id="team-full">完整工单与历史 ↗</a></div></div><button class="team-btn" id="team-close" aria-label="关闭任务">关闭</button></div><div class="team-dialog-body"><div class="team-flow"><div><b>01 提交</b>${c?'已登记固定版本':'等待交付候选'}</div><div><b>02 技术检查</b>${h(technical[x.technical]||x.technical)}</div><div><b>03 人工复核</b>${h(human[x.human]||x.human)}</div><div><b>04 合并</b>${x.merge?.state==='merged'?'已合并到本地主干':'尚未合并'}</div></div><div class="team-grid"><label class="team-field" for="team-owner">负责人<select id="team-owner" aria-label="负责人" ${active?'':'disabled'}>${teamOptions(a.assignee)}</select></label><label class="team-field" for="team-reviewer">独立复核人<select id="team-reviewer" aria-label="独立复核人" ${active?'':'disabled'}>${teamOptions(a.reviewer)}</select></label></div><div class="team-actions" style="margin-top:12px"><button class="team-btn" id="team-assign" ${active?'':'disabled'}>保存分配</button><span class="team-muted">负责人推进实现，另一位成员复核交付。</span></div><div id="team-message" role="status" aria-live="polite"></div><p id="team-access-note" class="team-note" role="status" hidden></p>${x.requests.length?`<div class="team-note">有 ${x.requests.length} 项操作结果尚未确认。请核对运行与事件后处理，不要重复启动。${x.requests.map(r=>`<div class="team-code">${h(r.request_id)} · ${h(r.state)} · ${h(r.error)}</div>`).join('')}</div>`:''}<section class="team-section"><h3>需求与验收标准</h3><div class="team-description">${md(t.body||'尚未填写需求详情。')}</div></section>
 ${c?teamCandidatePanel(x):`<section class="team-section"><h3>提交代码</h3>${x.can_submit&&!t.links?.hold?'<button class="team-btn" id="team-claim">接管任务，准备独立提交</button>':''}<div class="team-muted">将已经存在于项目仓库的提交登记为固定候选，再运行独立检查。CLI / MCP 和已有人工交付流程也可以继续使用。</div>${x.run?`<div class="team-note">已有运行 #${x.run.id}，当前状态 ${h(x.run.status)}。<a href="#/t/${h(t.key)}" data-team-exit>打开工单查看运行与原有交付流程</a>${x.run.can_recheck?`<button class="team-btn" id="team-run-recheck" style="margin-left:10px">重新技术检查</button>`:''}</div>`:''}${teamSubmitForm(x)}</section>`}
 ${c?`<details class="team-section"><summary>提交修改后的新候选</summary>${teamSubmitForm(x)}</details>`:''}${x.acceptance_memory?teamMemoryPanel(x.acceptance_memory):''}<section class="team-section"><h3>沟通与交接</h3><label class="team-field">补充当前任务的事实、问题或交接说明<textarea id="team-comment" placeholder="说明已完成的工作、下一步及需要协助的事项"></textarea></label><div class="team-actions" style="margin-top:12px"><button class="team-btn" id="team-comment-send" ${active?'':'disabled'}>记录到任务</button><span class="team-muted">沟通会成为需求依据，已有候选可能需要重新确认。</span></div><div id="team-history"></div></section><div class="team-note">${h(x.boundary)}</div></div>`;
 teamAccessGuard(dialog,x);document.body.appendChild(dialog);dialog.showModal();dialog.querySelector('#team-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialog.remove();if(teamState.dialog===dialog)teamState.dialog=null});dialog.querySelectorAll('#team-full,[data-team-exit]').forEach(el=>el.onclick=()=>dialog.close());
 const message=(text,bad=false)=>{const el=dialog.querySelector('#team-message');if(el){el.className=bad?'team-error':'team-feedback';el.textContent=text}};
 const act=async(body,success)=>{const denial=teamAccessReason(x,body.action);if(denial){message(denial,true);return}if(teamState.busy)return;teamState.busy=true;const disabled=new Map(Array.from(dialog.querySelectorAll('button'),b=>[b,b.disabled]));dialog.querySelectorAll('button').forEach(b=>b.disabled=true);message('正在保存操作…');try{const signature=JSON.stringify({viewer:teamState.data.viewer,ticket:key,...body});const requestId=teamState.requests.get(signature)||teamRequest();teamState.requests.set(signature,requestId);let result;try{result=await post('/api/team',{ticket:key,request_id:requestId,...body})}catch(error){try{const receipt=await get('/api/team?request_id='+encodeURIComponent(requestId));if(!receipt.request||receipt.request.state==='failed')teamState.requests.delete(signature)}catch(readError){}throw error}teamState.requests.delete(signature);const i=teamState.data.items.findIndex(v=>v.ticket.key===key);if(i>=0)teamState.data.items[i]=result.item;teamState.busy=false;const stillOpen=dialog.isConnected&&dialog.open;let refreshError='';try{await teamRefreshList()}catch(error){refreshError='；列表刷新失败，请重新读取列表：'+error.message}if(stillOpen&&dialog.isConnected&&dialog.open){const opened=await teamOpen(key,result.item);const fresh=opened?.isConnected&&opened.open?opened.querySelector('#team-message'):null;if(fresh){fresh.className=result?.result?.memory?.pending?'team-error':'team-feedback';fresh.textContent=success+teamMemoryFeedback(result)+refreshError}}return result}catch(error){message(error.message,true)}finally{teamState.busy=false;if(dialog.isConnected)disabled.forEach((value,b)=>b.disabled=value)}};
 const acceptanceMemory=x.acceptance_memory;
 if(acceptanceMemory){dialog.querySelector('#team-memory-open').onclick=()=>{dialog.close();memSelectProject(acceptanceMemory.project);MEM.query='';memNavigate('lessons')};dialog.querySelector('#team-memory-retry')?.addEventListener('click',()=>act({action:'business_accept',candidate_id:acceptanceMemory.candidate_id,evidence_hash:acceptanceMemory.evidence_hash,result:acceptanceMemory.result,note:acceptanceMemory.note},'本次验收记录已核对'))}
 dialog.querySelector('#team-assign').onclick=()=>act({action:'assign',assignee:dialog.querySelector('#team-owner').value,reviewer:dialog.querySelector('#team-reviewer').value,revision:a.revision,previous_assignee:a.assignee},'分配已保存');
 dialog.querySelector('#team-claim')?.addEventListener('click',()=>act({action:'claim'},'已接管任务，可提交固定候选'));
 dialog.querySelector('#team-comment-send').onclick=()=>act({action:'comment',body:dialog.querySelector('#team-comment').value},'交接已记录，请核对候选依据是否仍有效');
 dialog.querySelector('#team-run-recheck')?.addEventListener('click',()=>act({action:'run_recheck',run_id:x.run.id},'已启动独立技术检查，请查看运行记录'));
 dialog.querySelector('#team-submit')?.addEventListener('click',()=>{try{const lines=dialog.querySelector('#team-submit-criteria').value.split('\n').filter(s=>s.trim());const criteria=lines.map((line,i)=>{const parts=line.split('|');if(parts.length!==2||parts.some(p=>!p.trim()))throw Error('每行填写“验收要求 | 实际验证方式”');return{id:'AC'+(i+1),text:parts[0].trim(),check:parts[1].trim()}});act({action:'candidate_submit',base_commit:dialog.querySelector('#team-base').value.trim(),commit:dialog.querySelector('#team-commit').value.trim(),requirement_hash:x.requirement_hash,criteria,summary:dialog.querySelector('#team-summary').value},'已登记固定候选，下一步运行技术检查')}catch(error){message(error.message,true)}});
 if(c){const action=(name,extra={})=>act({action:name,candidate_id:c.id,...extra},{candidate_verify:'已启动独立检查，请刷新查看结果',candidate_preview:'已请求固定版本预览',candidate_cancel:'已请求停止检查，请核对停止回执',candidate_merge:'已合并到本地主干，尚未推送或部署',business_accept:'业务验收结果已记录，历史证据完整保留'}[name]||'操作已记录');dialog.querySelector('#team-verify')?.addEventListener('click',()=>action('candidate_verify'));dialog.querySelector('#team-preview')?.addEventListener('click',()=>action('candidate_preview'));dialog.querySelector('#team-cancel')?.addEventListener('click',()=>action('candidate_cancel'));dialog.querySelector('#team-refresh')?.addEventListener('click',async()=>{try{const all=await get('/api/team?view=team&project='+encodeURIComponent(t.pkey||t.key.slice(0,t.key.lastIndexOf('-')))+'&ticket='+encodeURIComponent(key));const next=all.items.find(v=>v.ticket.key===key);if(next&&dialog.isConnected&&dialog.open){await teamRefreshList();if(dialog.isConnected&&dialog.open)teamOpen(key,next);}else message('请返回团队列表刷新当前任务',true)}catch(error){message(error.message,true)}});
 dialog.querySelector('#team-assess')?.addEventListener('click',()=>action('candidate_assess',{verification_hash:c.verification_hash,preview_hash:c.preview_hash,results:c.criteria.map((criterion,i)=>({id:criterion.id,status:dialog.querySelector('#team-result-'+i).value,evidence:dialog.querySelector('#team-evidence-'+i).value})),note:dialog.querySelector('#team-review-note').value}));
 for(const [id,decision] of [['team-accept','accept'],['team-reject','reject']])dialog.querySelector('#'+id)?.addEventListener('click',()=>action('review',{evidence_hash:c.evidence_hash,decision,note:dialog.querySelector('#team-review-note').value}));dialog.querySelector('#team-merge')?.addEventListener('click',()=>action('candidate_merge',{evidence_hash:c.evidence_hash}));dialog.querySelector('#team-business-pass')?.addEventListener('click',()=>action('business_accept',{evidence_hash:c.evidence_hash,result:'pass',note:dialog.querySelector('#team-review-note').value}));dialog.querySelector('#team-business-fail')?.addEventListener('click',()=>action('business_accept',{evidence_hash:c.evidence_hash,result:'fail',note:dialog.querySelector('#team-review-note').value}));}
 try{const packet=await get('/api/tickets/'+encodeURIComponent(key));if(dialog.isConnected)dialog.querySelector('#team-history').innerHTML=packet.events.filter(e=>['comment','team_assignment','candidate_decision','candidate_merge'].includes(e.kind)).map(e=>`<div class="team-history"><span class="team-muted">${h(e.author)} · ${h(e.ts)}</span><br>${h(e.body)}</div>`).join('')}catch(error){if(dialog.isConnected)dialog.querySelector('#team-history').textContent='沟通记录暂时不可读：'+error.message}
 return dialog;
}
function teamSubmitForm(x){return `<div class="team-grid" style="margin-top:16px"><label class="team-field">基线提交（完整 40 位）<input id="team-base" autocomplete="off" value="${h(x.candidate?.base_commit||'')}" placeholder="本次改动基于哪个提交"></label><label class="team-field">交付提交（完整 40 位）<input id="team-commit" autocomplete="off" placeholder="仓库中已经存在的提交"></label></div><label class="team-field" style="margin-top:14px">实现说明<textarea id="team-summary" placeholder="说明实际完成了什么，以及仍未验证的边界"></textarea></label><label class="team-field" style="margin-top:14px">逐项验收标准，每行一条<textarea id="team-submit-criteria" placeholder="保存后刷新仍可查看 | 创建一条记录，刷新后核对内容">${h((x.candidate?.criteria||[]).map(c=>c.text+' | '+c.check).join('\n'))}</textarea><span>每行填写：验收要求 | 实际验证方式</span></label><button class="team-btn team-btn-primary" id="team-submit" style="margin-top:12px" ${x.can_submit?'':'disabled'}>登记候选提交</button>${x.can_submit?'':'<div class="team-muted" style="margin-top:8px">请由已分配的负责人提交代码。</div>'}`}
function teamCandidatePanel(x){const c=x.candidate,review=x.can_review;return `<section class="team-section"><h3>固定候选与技术证据</h3><div class="team-code">${h(c.commit)}</div><div class="team-muted" style="margin-top:7px">提交者 ${h(c.author)} · 候选 #${c.id} · 运行 #${c.run_id}</div><div class="team-description" style="margin-top:12px">${md(c.summary)}</div>${c.missing.length?`<div class="team-note">${c.missing.map(h).join('<br>')}</div>`:''}<div class="team-actions"><button class="team-btn" id="team-verify" ${c.current&&!c.recheck?.running?'':'disabled'}>运行技术检查</button>${c.recheck?.running?'<button class="team-btn" id="team-cancel">停止检查</button>':''}<button class="team-btn" id="team-preview" ${c.current&&c.verification_passed?'':'disabled'}>启动固定版本预览</button>${c.preview_url?`<a class="team-btn" href="${h(c.preview_url)}" target="_blank" rel="noopener">打开预览 ↗</a>`:''}<button class="team-btn" id="team-refresh">刷新证据</button></div><details style="margin-top:15px"><summary>检查命令与完整结果</summary>${(c.verification?.commands||[]).map(cmd=>`<div class="team-history"><div class="team-code">${h(cmd.command||cmd.cmd||cmd.kind||'检查')} · 退出码 ${h(String(cmd.exit_code))}</div><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${h(cmd.output||'')}</pre></div>`).join('')||'<div class="team-muted">尚无本次版本的独立检查记录。</div>'}</details></section><section class="team-section"><h3>逐项复核与人工决定</h3>${c.author===teamState.data.viewer?'<div class="team-note">你是此固定候选的提交者。请指定另一位成员复核；重新分配负责人不会改变候选作者。</div>':''}<div class="team-muted" style="margin-bottom:14px">${review?'你是当前指定复核人，请实际核对预览和证据。':'由 '+h(x.assignment.reviewer||'待指定的独立成员')+' 复核；实现者不能自行代签。'}</div><div class="team-criteria">${c.criteria.map((criterion,i)=>{const result=c.assessment?.results?.find(r=>r.id===criterion.id);return `<div class="team-criterion"><div class="team-title">${h(criterion.id)} · ${h(criterion.text)}</div><div class="team-muted" style="margin:5px 0 12px">验证方式：${h(criterion.check)}</div><div class="team-grid"><label class="team-field">实际结论<select id="team-result-${i}" ${review?'':'disabled'}>${[['unknown','未验证'],['pass','通过'],['fail','不通过']].map(([value,label])=>`<option value="${value}" ${(result?.status||'unknown')===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="team-field">实际操作与证据<textarea id="team-evidence-${i}" ${review?'':'disabled'} placeholder="记录操作、预期与实际结果，以及证据位置">${h(result?.evidence||'')}</textarea></label></div></div>`}).join('')}</div><label class="team-field" style="margin-top:14px">复核说明<textarea id="team-review-note" ${review?'':'disabled'} placeholder="说明核对范围、结果及仍存在的限制"></textarea></label><div class="team-actions" style="margin-top:14px"><button class="team-btn" id="team-assess" ${review&&c.current&&c.verification_passed&&c.preview_ready?'':'disabled'}>保存逐项技术复核</button><button class="team-btn team-btn-primary" id="team-accept" ${review&&c.ready_for_human?'':'disabled'}>人工复核通过</button><button class="team-btn" id="team-reject" ${review&&c.current?'':'disabled'}>退回修改</button>${x.state==='approved'?`<button class="team-btn team-btn-primary" id="team-merge" ${review?'':'disabled'}>合并到本地主干</button>`:''}${x.state==='merged'?`<button class="team-btn team-btn-primary" id="team-business-pass" ${review?'':'disabled'}>业务验收通过</button><button class="team-btn" id="team-business-fail" ${review?'':'disabled'}>业务验收退回</button>`:''}</div>${c.human_decision?`<div class="team-muted" style="margin-top:12px">最近人工记录：${h(c.human_decision.author)} · ${h(c.human_decision.created)} · ${h(c.human_decision.note)}${c.human_accepted?'':'（不代表当前版本已通过）'}</div>`:''}</section>`}
"""
